import{_ as e,o as n,c as i,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"UC 08 — Admin Functions (UC-128 – UC-141)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/08-admin-functions.md","filePath":"ba/use-cases/08-admin-functions.md"}'),d={name:"ba/use-cases/08-admin-functions.md"};function c(s,t,a,l,r,g){return n(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="uc-08-—-admin-functions-uc-128-–-uc-141" tabindex="-1">UC 08 — Admin Functions (<code>UC-128</code> – <code>UC-141</code>) <a class="header-anchor" href="#uc-08-—-admin-functions-uc-128-–-uc-141" aria-label="Permalink to &quot;UC 08 — Admin Functions (`UC-128` – `UC-141`)&quot;">​</a></h1><p>&gt; <a href="./07-subscription.html">&lt;&lt; 07-subscription.md</a> | <a href="./README.html">UC Index</a> | <a href="./../09-admin-functions.html">Domain BA Spec: 09-admin-functions.md</a> | <a href="./../README.html">BA Overview &gt;&gt;</a> &gt; &gt; Đồng bộ chuẩn xác 1-đối-1 với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> và <code>AGENTS.md</code>. Chỉ sử dụng <strong>6 Vai trò Hệ thống Chuẩn (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-use-cases-14-ucs" tabindex="-1">1. Bảng Tổng Hợp Use Cases (14 UCs) <a class="header-anchor" href="#_1-bang-tong-hop-use-cases-14-ucs" aria-label="Permalink to &quot;1. Bảng Tổng Hợp Use Cases (14 UCs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">UC ID</th><th style="text-align:left;">Use Case Title</th><th style="text-align:left;">Canonical Actor(s)</th><th style="text-align:center;">Related FR</th><th style="text-align:left;">Business Rules</th></tr></thead><tbody><tr><td style="text-align:center;"><code>UC-128</code></td><td style="text-align:left;">Push Notification</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.1</code></td><td style="text-align:left;"><code>BR-62, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-129</code></td><td style="text-align:left;">Platform Statistics Overview</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.2</code></td><td style="text-align:left;"><code>BR-61, BR-62</code></td></tr><tr><td style="text-align:center;"><code>UC-130</code></td><td style="text-align:left;">System Health Monitoring</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.3</code></td><td style="text-align:left;"><code>BR-62, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-131</code></td><td style="text-align:left;">Content Moderation Queue</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.4</code></td><td style="text-align:left;"><code>BR-42, BR-62, BR-63, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-132</code></td><td style="text-align:left;">Update User Violation Status</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.5</code></td><td style="text-align:left;"><code>BR-62, BR-63, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-133</code></td><td style="text-align:left;">View User</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.6</code></td><td style="text-align:left;"><code>BR-62</code></td></tr><tr><td style="text-align:center;"><code>UC-134</code></td><td style="text-align:left;">Create User</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.7</code></td><td style="text-align:left;"><code>BR-01, BR-62, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-135</code></td><td style="text-align:left;">Update User</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.8</code></td><td style="text-align:left;"><code>BR-11, BR-15, BR-62, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-136</code></td><td style="text-align:left;">Deactivate User</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.9</code></td><td style="text-align:left;"><code>BR-05, BR-62, BR-63, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-137</code></td><td style="text-align:left;">View AI Credit Price List</td><td style="text-align:left;"><code>Owner</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.10.10</code></td><td style="text-align:left;"><code>BR-48, BR-62, BR-64</code></td></tr><tr><td style="text-align:center;"><code>UC-138</code></td><td style="text-align:left;">Update AI Credit Price</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.11</code></td><td style="text-align:left;"><code>BR-48, BR-62, BR-64, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-139</code></td><td style="text-align:left;">Import AI Credit Price CSV</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.12</code></td><td style="text-align:left;"><code>BR-62, BR-64, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-140</code></td><td style="text-align:left;">View Revenue Dashboard</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.13</code></td><td style="text-align:left;"><code>BR-59, BR-61, BR-62</code></td></tr><tr><td style="text-align:center;"><code>UC-141</code></td><td style="text-align:left;">Export Report File PDF</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.10.14</code></td><td style="text-align:left;"><code>BR-61, BR-62, BR-65</code></td></tr></tbody></table><hr><h2 id="uc-128-—-push-notification" tabindex="-1">UC-128 — Push Notification <a class="header-anchor" href="#uc-128-—-push-notification" aria-label="Permalink to &quot;UC-128 — Push Notification&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.1</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-62, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG58</code></li><li><strong>Specification &amp; Flow:</strong> Tạo và phát thông báo toàn hệ thống (System Broadcast / Push Notification — /admin/notifications). Cho phép Admin soạn tiêu đề, nội dung, mức độ ưu tiên và phân nhóm đối tượng người nhận cụ thể (Tất cả người dùng, chỉ Owners, theo gói đăng ký Basic/Pro/Enterprise hoặc theo vai trò) để đẩy thông báo thời gian thực qua WebSocket, FCM Mobile và Email (BR-62).</li></ul><hr><h2 id="uc-129-—-platform-statistics-overview" tabindex="-1">UC-129 — Platform Statistics Overview <a class="header-anchor" href="#uc-129-—-platform-statistics-overview" aria-label="Permalink to &quot;UC-129 — Platform Statistics Overview&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.2</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-61, BR-62</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36</code></li><li><strong>Specification &amp; Flow:</strong> Xem bảng điều khiển thống kê tổng quan toàn nền tảng (Platform Statistics Overview — /admin/dashboard). Hiển thị các chỉ số vận hành cốt lõi và biểu đồ tăng trưởng: Tổng số người dùng, Số lượng Agency &amp; Workspace đang hoạt động, Tổng số bài đăng xuất bản thành công qua 4 mạng xã hội, Lưu lượng gọi AI và Tổng doanh thu hệ thống (BR-62).</li></ul><hr><h2 id="uc-130-—-system-health-monitoring" tabindex="-1">UC-130 — System Health Monitoring <a class="header-anchor" href="#uc-130-—-system-health-monitoring" aria-label="Permalink to &quot;UC-130 — System Health Monitoring&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.3</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-62, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Giám sát sức khỏe và mức tiêu thụ tài nguyên thời gian thực của toàn bộ cụm Microservices (System Health Monitoring — /admin/health). Hiển thị trạng thái sống (UP/DOWN/DEGRADED), tỷ lệ % CPU, % RAM, độ trễ phản hồi API, độ dài hàng đợi RabbitMQ và kết nối cơ sở dữ liệu (PostgreSQL, MongoDB, Redis, ChromaDB, Neo4j) của từng dịch vụ (API Gateway, Business, Publisher, AI Service) (BR-62).</li></ul><hr><h2 id="uc-131-—-content-moderation-queue" tabindex="-1">UC-131 — Content Moderation Queue <a class="header-anchor" href="#uc-131-—-content-moderation-queue" aria-label="Permalink to &quot;UC-131 — Content Moderation Queue&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.4</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-42, BR-62, BR-63, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG36, MSG58</code></li><li><strong>Specification &amp; Flow:</strong> Xem và xử lý hàng đợi kiểm duyệt các nội dung bị gắn cờ vi phạm chính sách toàn hệ thống (Content Moderation Queue — /admin/moderation). Hiển thị các nội dung do người dùng/AI tạo ra bị bộ lọc tự động nghi ngờ vi phạm tiêu chuẩn an toàn; Admin kiểm tra chi tiết bằng chứng để đưa ra quyết định phê duyệt cho phép lưu hành (Approve/Dismiss) hoặc xác nhận vi phạm để gỡ bỏ và cảnh cáo (Confirm Violation) (BR-42, BR-63).</li></ul><hr><h2 id="uc-132-—-update-user-violation-status" tabindex="-1">UC-132 — Update User Violation Status <a class="header-anchor" href="#uc-132-—-update-user-violation-status" aria-label="Permalink to &quot;UC-132 — Update User Violation Status&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.5</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-62, BR-63, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG36, MSG59</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật trực tiếp trạng thái xử lý vi phạm và xác minh của tài khoản người dùng trên hệ thống (Update User Violation Status — /admin/users/:userId/status). Cho phép Admin chuyển đổi trạng thái tài khoản giữa ACTIVE (Hoạt động bình thường / Đã xác minh), WARNED (Cảnh cáo vi phạm), SUSPENDED (Tạm đình chỉ có thời hạn) và BANNED (Khóa vĩnh viễn kèm thu hồi toàn bộ phiên đăng nhập trên Redis); bắt buộc ghi lý do vào nhật ký kiểm toán (Audit Log, BR-65, BR-63, BR-65).</li></ul><hr><h2 id="uc-133-—-view-user" tabindex="-1">UC-133 — View User <a class="header-anchor" href="#uc-133-—-view-user" aria-label="Permalink to &quot;UC-133 — View User&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.6</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-62</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem, tìm kiếm và lọc danh sách toàn bộ tài khoản người dùng trên hệ thống (View User — /admin/users). Hỗ trợ tìm kiếm theo Họ tên, Email, lọc theo Vai trò hệ thống, Trạng thái tài khoản (ACTIVE, PENDING_VERIFICATION, SUSPENDED, BANNED, DELETED) và xem chi tiết danh sách Agency/Workspace mà người dùng đó tham gia (BR-62).</li></ul><hr><h2 id="uc-134-—-create-user" tabindex="-1">UC-134 — Create User <a class="header-anchor" href="#uc-134-—-create-user" aria-label="Permalink to &quot;UC-134 — Create User&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.7</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-01, BR-62, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG04, MSG07, MSG08, MSG59</code></li><li><strong>Specification &amp; Flow:</strong> Tạo mới tài khoản người dùng trực tiếp từ cổng quản trị hệ thống (Create User — /admin/users/new). Admin nhập Họ tên, Email (kiểm tra duy nhất BR-01), Vai trò hệ thống và mật khẩu khởi tạo (hoặc gửi email thiết lập mật khẩu); hệ thống băm mật khẩu (BR-65), kích hoạt tài khoản và ghi nhận vào Audit Log (BR-62, BR-65).</li></ul><hr><h2 id="uc-135-—-update-user" tabindex="-1">UC-135 — Update User <a class="header-anchor" href="#uc-135-—-update-user" aria-label="Permalink to &quot;UC-135 — Update User&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.8</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-11, BR-15, BR-62, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG59</code></li><li><strong>Specification &amp; Flow:</strong> Chỉnh sửa thông tin hồ sơ hành chính và phân quyền cấp hệ thống của tài khoản người dùng (Update User — /admin/users/:userId/edit). Cho phép Admin cập nhật Họ tên, Số điện thoại, Vai trò hệ thống; ngăn chặn việc tự hạ quyền hoặc khóa tài khoản Admin cuối cùng đang hoạt động trên hệ thống (BR-62, BR-65, BR-65).</li></ul><hr><h2 id="uc-136-—-deactivate-user" tabindex="-1">UC-136 — Deactivate User <a class="header-anchor" href="#uc-136-—-deactivate-user" aria-label="Permalink to &quot;UC-136 — Deactivate User&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.9</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-05, BR-62, BR-63, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG36, MSG59</code></li><li><strong>Specification &amp; Flow:</strong> Tạm khóa / vô hiệu hóa tài khoản người dùng từ cổng quản trị (Deactivate User — /admin/users/:userId). Chuyển trạng thái tài khoản sang INACTIVE/DEACTIVATED, lập tức thu hồi toàn bộ JWT token đang hoạt động trên Redis (BR-63), chặn đăng nhập mới (BR-05) nhưng vẫn bảo toàn dữ liệu lịch sử và ghi vết Audit Log (BR-63, BR-65).</li></ul><hr><h2 id="uc-137-—-view-ai-credit-price-list" tabindex="-1">UC-137 — View AI Credit Price List <a class="header-anchor" href="#uc-137-—-view-ai-credit-price-list" aria-label="Permalink to &quot;UC-137 — View AI Credit Price List&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.10</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-48, BR-62, BR-64</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem bảng cấu hình đơn giá tiêu hao AI Credit hiện hành của toàn hệ thống (View AI Credit Price List — /admin/credit-prices). Hiển thị danh mục đầy đủ các tác vụ AI (Generate Caption, Generate Image Qwen Image 2.1 (ComfyUI GPU)/LoRA, Generate Video Veo, Generate Virtual Ambassador, Suggest Hashtag...), đơn giá AI Credit tương ứng, trạng thái kích hoạt và lịch sử cập nhật giá (BR-64).</li></ul><hr><h2 id="uc-138-—-update-ai-credit-price" tabindex="-1">UC-138 — Update AI Credit Price <a class="header-anchor" href="#uc-138-—-update-ai-credit-price" aria-label="Permalink to &quot;UC-138 — Update AI Credit Price&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.11</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-48, BR-62, BR-64, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG60</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật trực tiếp đơn giá tiêu hao AI Credit cho từng loại tác vụ AI trên giao diện quản trị (Update AI Credit Price — /admin/credit-prices). Hệ thống kiểm tra đơn giá phải là số nguyên dương hợp lệ; đơn giá mới được áp dụng ngay cho các yêu cầu sinh AI kế tiếp mà không làm thay đổi số credit đã khóa của các tiến trình AI đang chạy dở (BR-48, BR-64, BR-65).</li></ul><hr><h2 id="uc-139-—-import-ai-credit-price-csv" tabindex="-1">UC-139 — Import AI Credit Price CSV <a class="header-anchor" href="#uc-139-—-import-ai-credit-price-csv" aria-label="Permalink to &quot;UC-139 — Import AI Credit Price CSV&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.12</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-62, BR-64, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG22, MSG60</code></li><li><strong>Specification &amp; Flow:</strong> Tải lên, kiểm tra xem trước (Preview) và nhập hàng loạt bảng đơn giá AI Credit từ tệp CSV (Import AI Credit Price CSV — /admin/credit-prices/import). Hệ thống phân tích cú pháp từng dòng trong tệp CSV (feature_code, model_tier, credit_cost, description), báo lỗi chi tiết nếu có mã tác vụ không tồn tại hoặc đơn giá âm, và áp dụng cập nhật nguyên tử (all-or-nothing transaction) khi Admin xác nhận (BR-64, BR-65).</li></ul><hr><h2 id="uc-140-—-view-revenue-dashboard" tabindex="-1">UC-140 — View Revenue Dashboard <a class="header-anchor" href="#uc-140-—-view-revenue-dashboard" aria-label="Permalink to &quot;UC-140 — View Revenue Dashboard&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.13</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-59, BR-61, BR-62</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem bảng điều khiển phân tích doanh thu toàn hệ thống (View Revenue Dashboard — /admin/revenue). Thống kê tổng doanh thu thực thu từ các giao dịch đã thanh toán thành công (PAID), biểu đồ xu hướng doanh thu theo Ngày/Tuần/Tháng/Quý, cơ cấu doanh thu giữa Gói đăng ký (Subscription Plans: Basic, Pro, Enterprise) và Gói mua thêm AI Credit (Top-up Packs) (BR-61, BR-62).</li></ul><hr><h2 id="uc-141-—-export-report-file-pdf" tabindex="-1">UC-141 — Export Report File PDF <a class="header-anchor" href="#uc-141-—-export-report-file-pdf" aria-label="Permalink to &quot;UC-141 — Export Report File PDF&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.10.14</code> (3.10 Admin Functions)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-61, BR-62, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG60</code></li><li><strong>Specification &amp; Flow:</strong> Kết xuất và tải xuống tệp báo cáo quản trị định dạng PDF (Export Report File PDF — /admin/reports/export). Cho phép Admin chọn loại báo cáo (Báo cáo Doanh thu &amp; Giao dịch, Báo cáo Tăng trưởng Người dùng &amp; Agency, Báo cáo Tiêu thụ AI Credit) và khoảng thời gian lọc để hệ thống tổng hợp số liệu, biểu đồ và xuất ra tệp PDF chuẩn phục vụ lưu trữ và báo cáo (BR-62, BR-65).</li></ul>',47)])])}const m=e(d,[["render",c]]);export{u as __pageData,m as default};
